-- Howling Fjord: creature abilities
-- Most of the zone's creatures (the vrykul, the Scourge, the Forsaken and their foes, the worgen and wildlife) had no AI or ran
-- classic rows: port their abilities from the classic (AzerothCore) data, falling back to the Cataclysm data; rows needing events,
-- actions or action lists LoA lacks are left out, and AzerothCore's range and area events are converted. The creatures no reference
-- scripts cast their sniffed spells (creature_template spell1-8).

SET @ENTRIES := '23651,23652,23658,23660,23680,23690,23691,23739,23772,23842,23844,23874,23883,23932,24014,24018,24019,24023,24029,24030,24051,24063,24169,24173,24216,24235,24236,24249,24250,24251,24271,24316,24340,24371,24440,24459,24460,24461,24533,24546,24635,24638,24673,24676,24677,24789,24791,24797,24871,24872,24883,29394,29479,29486,29487,32377';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '23575,23643,23644,23645,23653,23654,23655,23656,23657,23674,23676,23677,23688,23711,23740,23744,23779,23793,23794,23796,23851,23865,23866,23871,23875,23886,23887,23919,23940,23945,23946,23962,23963,23964,23982,23983,23992,23993,23994,24026,24031,24050,24073,24104,24116,24128,24132,24195,24197,24212,24262,24317,24334,24398,24400,24475,24478,24485,24514,24516,24517,24540,24547,24633,24644,24681,24812,24899,24901,25026,25224,26663,26823,26825,26826,26827,27167,27927,31715,51883,51884,51885,51886,51892';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
